  series: [{ show: 'spreekwoord', who: 'нидерландская пословица', q: 'Rome is ook niet in één dag gebouwd.', mean: '«Рим тоже не за один день построили» — большое дело требует времени.', fun: 'Пословица — в пассиве (<i>is gebouwd</i>, без <i>geworden</i>!). Её говорят, когда что-то идёт медленно: ремонт, учёба, новая железная дорога. Йоп говорит её о своём нидерландском. И о своём терпении.', use: 'Rustig aan, Rome is ook niet in één dag gebouwd.', qz: '«Rome is ook niet in één dag gebouwd» говорят, когда…|дело требует времени|кто-то опоздал|ремонт не нужен # Терпение.' }],
  write: { h: 'Короткая «новость» (в духе NOS) о событии в вашем городе: что построили, открыли, запретили. Минимум 5 форм пассива.', min: 100, use: ['wordt', 'werd', 'is', 'door', 'er wordt'],
    plan: ['Заголовок: что случилось.', 'Что делают сейчас (wordt).', 'Что сделали раньше (werd / is).', 'Кем (door) и что будет дальше (zal … worden).'],
    model: 'Nieuwe brug in Riga geopend\nGisteren is in Riga een nieuwe fietsbrug geopend. De brug werd in twee jaar gebouwd en is door een Nederlands bureau ontworpen.\nEr wordt verwacht dat elke dag duizenden fietsers de brug gebruiken. Auto’s worden er niet toegelaten.\nVolgend jaar zal ook de oude brug gerepareerd worden. Tot die tijd wordt het verkeer omgeleid.' },
  vid: [['Learn Dutch with Bart de Pau', 'Dutch passive voice worden'], ['NOS Jeugdjournaal', 'Baarle-Nassau grens'], ['DutchPod101', 'passive voice Dutch']],
