  src: [['DutchGrammar.com — passive', 'https://www.dutchgrammar.com/'], ['ANS — Algemene Nederlandse Spraakkunst', 'https://e-ans.ivdnt.org/'], ['Woordenlijst', 'https://woordenlijst.org/']],
